/* PULSEWALL — volatile metric monitor · cell-j04-s04 */
:root{
  --bg:#0a0e14; --panel:#101823; --panel2:#0c1219;
  --line:#1b2836; --line2:#26374a;
  --tx:#dbe4ee; --mut:#7e8fa3; --faint:#55657a;
  --ok:#3bd98c; --warn:#f2b63b; --crit:#ff5f5f; --acc:#4da3ff; --spike:#b48cff;
  --mono:ui-monospace,"Cascadia Mono",Consolas,Menlo,monospace;
  --sans:system-ui,"Segoe UI",Roboto,"PingFang SC","Microsoft YaHei",sans-serif;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;background:var(--bg);color:var(--tx);font:13px/1.45 var(--sans);overflow:hidden}
#app{display:flex;flex-direction:column;height:100vh}
::-webkit-scrollbar{width:10px;height:10px}
::-webkit-scrollbar-thumb{background:#24303e;border-radius:5px;border:2px solid var(--bg)}
::-webkit-scrollbar-track{background:transparent}
button{font:inherit;color:inherit;background:none;border:none;cursor:pointer}
input{font:inherit}

/* ---------- header ---------- */
#hdr{display:flex;align-items:center;gap:18px;height:58px;padding:0 14px;
  border-bottom:1px solid var(--line);background:linear-gradient(180deg,#0e141d,#0b1017);flex:none}
.brand{display:flex;align-items:center;gap:10px;min-width:0}
.live{width:9px;height:9px;border-radius:50%;background:var(--ok);box-shadow:0 0 8px var(--ok);flex:none;animation:pulse 2s ease-in-out infinite}
.live.paused{background:var(--faint);box-shadow:none;animation:none}
@keyframes pulse{0%,100%{opacity:1}50%{opacity:.35}}
.brand-tx h1{margin:0;font-size:15px;font-weight:700;letter-spacing:.14em}
.brand-tx .sub{font-size:10.5px;color:var(--mut);letter-spacing:.04em}

.stats{display:flex;align-items:center;gap:14px;margin-left:6px}
.stat{font-size:11px;color:var(--mut);white-space:nowrap}
.stat b{font:600 15px/1 var(--mono);color:var(--tx);margin-right:5px;font-variant-numeric:tabular-nums}
.stat.sev-ok b{color:var(--ok)}
.stat.sev-warn b{color:var(--warn)}
.stat.sev-crit b{color:var(--crit)}
.stat.crit-flash b{animation:pulse 1.2s ease-in-out infinite}
.stat.clock b{font-size:13px;font-weight:500}

.ctrl{margin-left:auto;display:flex;align-items:center;gap:8px}
#q{width:190px;height:28px;padding:0 10px;border-radius:6px;border:1px solid var(--line2);
  background:var(--panel2);color:var(--tx);outline:none}
#q:focus{border-color:var(--acc)}
#q::placeholder{color:var(--faint)}
.fgrp{display:flex;border:1px solid var(--line2);border-radius:6px;overflow:hidden}
.fbtn{height:28px;padding:0 10px;font-size:11.5px;color:var(--mut);border-right:1px solid var(--line2)}
.fbtn:last-child{border-right:none}
.fbtn.on{background:#1b2c40;color:var(--tx)}
.fbtn:hover{color:var(--tx)}
.pbtn{height:28px;padding:0 12px;border:1px solid var(--line2);border-radius:6px;font-size:11.5px;color:var(--mut)}
.pbtn:hover{color:var(--tx);border-color:var(--faint)}
.pbtn[aria-pressed="true"]{background:#33261a;color:var(--warn);border-color:#5c4520}

/* ---------- fleet strip ---------- */
#strip{display:flex;gap:2px;padding:8px 14px 0;flex:none}
.seg{flex:1;height:11px;border-radius:2px;background:#212f3e;cursor:pointer;transition:background .3s}
.seg[data-sev="ok"]{background:#2b5142}
.seg[data-sev="warn"]{background:var(--warn)}
.seg[data-sev="crit"]{background:var(--crit);box-shadow:0 0 6px rgba(255,95,95,.7)}
.seg.gap{margin-left:9px}
.seg.hide{visibility:hidden}
.seg.sel{outline:2px solid var(--acc);outline-offset:1px}
.seg:hover{filter:brightness(1.35)}

/* ---------- main layout ---------- */
#main{display:flex;flex:1;min-height:0;padding:10px 14px 12px;gap:10px}
#grid{flex:1;min-width:0;overflow-y:auto;padding-right:2px}
#side{width:404px;flex:none;display:flex;flex-direction:column;gap:10px;min-height:0}
@media (max-width:1280px){#side{width:344px}}

.panel{background:var(--panel);border:1px solid var(--line);border-radius:9px;display:flex;flex-direction:column;min-height:0}
.p-head{display:flex;align-items:baseline;gap:8px;padding:9px 12px 7px;border-bottom:1px solid var(--line);flex:none}
.p-head h2{margin:0;font-size:11px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:var(--mut)}
.p-sub{margin-left:auto;font-size:10.5px;color:var(--faint);font-family:var(--mono)}
.empty{padding:18px 14px;color:var(--faint);font-size:12px}

/* ---------- metric grid ---------- */
.group{margin-bottom:14px}
.g-head{position:sticky;top:0;z-index:2;display:flex;align-items:baseline;gap:8px;
  padding:5px 2px 6px;background:linear-gradient(180deg,var(--bg) 82%,transparent)}
.g-name{font-size:11.5px;font-weight:700;letter-spacing:.09em;text-transform:uppercase;color:var(--mut)}
.g-ok{font-size:10.5px;color:var(--faint);font-family:var(--mono);font-variant-numeric:tabular-nums}
.g-ok[data-worst="warn"]{color:var(--warn)}
.g-ok[data-worst="crit"]{color:var(--crit)}
.g-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(206px,1fr));gap:9px}

.tile{background:var(--panel2);border:1px solid var(--line);border-radius:8px;
  padding:7px 10px 6px;cursor:pointer;user-select:none;position:relative;
  transition:background .35s,border-color .35s,box-shadow .35s}
.tile:hover{border-color:var(--line2)}
.tile:focus-visible{outline:2px solid var(--acc);outline-offset:1px}
.tile.sel{border-color:var(--acc)}
.tile.hide{display:none}
.tile[data-sev="warn"]{border-color:#6e5416;box-shadow:inset 3px 0 0 var(--warn);
  background:linear-gradient(180deg,rgba(242,182,59,.10),rgba(242,182,59,.02))}
.tile[data-sev="crit"]{border-color:#74302f;box-shadow:inset 3px 0 0 var(--crit),0 0 10px rgba(255,95,95,.12);
  background:linear-gradient(180deg,rgba(255,95,95,.13),rgba(255,95,95,.03))}
@keyframes locateglow{0%,100%{outline:0 solid transparent}35%{outline:3px solid var(--acc)}}
.tile.locate{animation:locateglow 1.5s ease-out 1}

.t-top{display:flex;align-items:center;gap:6px;min-width:0}
.dot{width:7px;height:7px;border-radius:50%;background:#3a4a5c;flex:none;transition:background .3s}
.tile[data-sev="warn"] .dot,.tile[data-sev="crit"] .dot{animation:pulse 1.3s ease-in-out infinite}
.tile[data-sev="warn"] .dot{background:var(--warn)}
.tile[data-sev="crit"] .dot{background:var(--crit)}
.t-name{font-size:11.5px;font-weight:600;color:#c3cfdd;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.t-grp{margin-left:auto;font-size:9.5px;color:var(--faint);letter-spacing:.06em;text-transform:uppercase;flex:none}
.t-mid{display:flex;align-items:baseline;gap:8px;margin:2px 0 1px}
.t-val{font:600 21px/1.15 var(--mono);font-variant-numeric:tabular-nums;white-space:nowrap}
.t-val i{font:400 10.5px var(--mono);font-style:normal;color:var(--faint);margin-left:3px}
.tile[data-sev="warn"] .t-num{color:var(--warn)}
.tile[data-sev="crit"] .t-num{color:var(--crit)}
.t-delta{font:500 10.5px var(--mono);margin-left:auto;font-variant-numeric:tabular-nums}
.t-delta.up{color:#e08b8b}
.t-delta.dn{color:#7fbfe0}
.t-delta.flat{color:var(--faint)}
.spark{display:block;width:100%;height:27px}
.t-since{font:500 10px var(--mono);color:var(--faint);margin-top:2px;min-height:13px;letter-spacing:.02em}
.t-since[data-sev="warn"]{color:var(--warn)}
.t-since[data-sev="crit"]{color:var(--crit)}

/* ---------- evidence feed ---------- */
#feedPanel{flex:0 0 41%;min-height:120px}
#feedList{flex:1;overflow-y:auto;padding:5px 6px}
.entry{display:flex;gap:9px;padding:7px 7px 6px;border-radius:7px;cursor:pointer;
  border:1px solid transparent;animation:slidein .3s ease-out}
@keyframes slidein{from{opacity:0;transform:translateY(-7px)}to{opacity:1;transform:none}}
.entry:hover{background:#141d29;border-color:var(--line)}
.entry.done{opacity:.5}
.e-dot{width:8px;height:8px;border-radius:50%;background:var(--faint);margin-top:4px;flex:none}
.entry[data-sev="warn"] .e-dot{background:var(--warn)}
.entry[data-sev="crit"] .e-dot{background:var(--crit);box-shadow:0 0 6px rgba(255,95,95,.8)}
.entry[data-sev="spike"] .e-dot{background:var(--spike)}
.entry:not(.done)[data-sev="crit"] .e-dot,.entry:not(.done)[data-sev="warn"] .e-dot{animation:pulse 1.3s ease-in-out infinite}
.e-main{min-width:0;flex:1}
.e-name{font-size:12px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.e-rule{font-size:10.5px;color:var(--mut);font-family:var(--mono);margin-top:1px;
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.e-peak{font-size:10px;color:var(--faint);font-family:var(--mono);margin-top:1px;font-variant-numeric:tabular-nums}
.e-side{display:flex;flex-direction:column;align-items:flex-end;gap:2px;flex:none}
.e-badge{font:700 9px var(--mono);letter-spacing:.08em;padding:2px 6px;border-radius:4px;
  background:#22303f;color:var(--mut)}
.entry[data-sev="warn"] .e-badge{background:rgba(242,182,59,.14);color:var(--warn)}
.entry[data-sev="crit"] .e-badge{background:rgba(255,95,95,.16);color:var(--crit)}
.entry[data-sev="spike"] .e-badge{background:rgba(180,140,255,.14);color:var(--spike)}
.e-dur{font:500 10.5px var(--mono);color:var(--tx);font-variant-numeric:tabular-nums}
.e-t0{font:400 9.5px var(--mono);color:var(--faint)}

/* ---------- trace panel ---------- */
#tracePanel{flex:1;min-height:200px}
#traceBody{display:flex;flex-direction:column;flex:1;min-height:0}
#trHead{padding:9px 12px 4px;flex:none}
.tr-line1{display:flex;align-items:center;gap:8px}
.tr-name{font-size:14px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.tr-name i{font:400 10.5px var(--sans);font-style:normal;color:var(--faint);margin-left:6px;text-transform:uppercase;letter-spacing:.06em}
.tr-actions{margin-left:auto;display:flex;gap:6px;flex:none}
.tbtn{height:22px;padding:0 9px;font-size:10.5px;border:1px solid var(--line2);border-radius:5px;color:var(--mut)}
.tbtn:hover{color:var(--tx);border-color:var(--faint)}
.tr-line2{display:flex;align-items:baseline;gap:10px;margin-top:2px}
.tr-val{font:600 24px/1.2 var(--mono);font-variant-numeric:tabular-nums}
.tr-val i{font:400 11px var(--mono);font-style:normal;color:var(--faint);margin-left:3px}
.tr-meta{font-size:10px;color:var(--faint);font-family:var(--mono);margin-top:1px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}

.badge{font:700 8.5px var(--mono);letter-spacing:.07em;padding:2px 6px;border-radius:4px;flex:none}
.badge.warn{background:rgba(242,182,59,.14);color:var(--warn)}
.badge.crit{background:rgba(255,95,95,.16);color:var(--crit)}
.badge.recover{background:rgba(59,217,140,.13);color:var(--ok)}
.badge.spike{background:rgba(180,140,255,.14);color:var(--spike)}
.badge.flat{background:rgba(242,182,59,.14);color:var(--warn)}

#chartWrap{position:relative;flex:none;margin:4px 12px 0;height:172px;border:1px solid var(--line);
  border-radius:7px;background:var(--panel2);overflow:hidden}
#chart{display:block;width:100%;height:100%;cursor:crosshair}
#xhair{position:absolute;transform:translate(-50%,-135%);pointer-events:none;white-space:nowrap;
  background:#1a2634;border:1px solid var(--line2);border-radius:5px;padding:3px 7px;
  font:500 10px var(--mono);color:var(--tx);box-shadow:0 3px 10px rgba(0,0,0,.5)}
#trLegend{display:flex;gap:12px;flex-wrap:wrap;padding:5px 14px 2px;font-size:9.5px;color:var(--faint);flex:none}
.sw{display:inline-block;width:10px;height:4px;border-radius:2px;margin-right:4px;vertical-align:middle}
.sw.line{background:var(--acc)}
.sw.warnb{background:rgba(242,182,59,.45)}
.sw.critb{background:rgba(255,95,95,.55)}

#evList{flex:1;overflow-y:auto;padding:4px 8px 8px;min-height:60px}
.ev-row{display:flex;align-items:center;gap:8px;padding:4px 4px;border-bottom:1px solid #131c27;font-size:11px}
.ev-t{font:500 10px var(--mono);color:var(--faint);flex:none;font-variant-numeric:tabular-nums}
.ev-note{color:var(--mut);font-family:var(--mono);font-size:10px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}

