});
qEl.addEventListener('input', () => {
  searchTerm = qEl.value.trim().toLowerCase();
  for (const m of METRICS) {
    const hit = !searchTerm || (m.name + ' ' + groupTag(m.gid) + ' ' + groupOf(m.gid).name).toLowerCase().includes(searchTerm);
