  M('edge-gw2-cpu', 'gw2 · cpu', 'edge', '%', 1, { base: 39, amp: 5, period: 80, noise: 2, dir: 'upBad', warn: 80, crit: 92, scripts: [burst(-150, -120, 26)] }),
  M('edge-gw3-sess', 'gw3 · sessions', 'edge', 'k', 2, { base: 12.4, amp: 1.1, period: 150, noise: .35 }),
