const GROUPS = [
  { id: 'edge', name: 'Edge Gateway', tag: 'edge' },
  { id: 'api', name: 'Payments API', tag: 'api' },
  { id: 'search', name: 'Search Index', tag: 'srch' },
  { id: 'ingest', name: 'Ingest Pipeline', tag: 'ing' },
