/* ---------------- stream config ---------------- */
const TICK_MS = 1000, HIST_MAX = 240, SPARK_N = 90, CHART_N = 180,
  DEBOUNCE = 2, RAMP = 15, SPIKE_Z = 4.2, FEED_MAX = 80, SPIKE_COALESCE = 8;
const ramp = (start, end, mag) => ({ type: 'ramp', start, end, mag });
