const METRICS = [
  /* ---- Edge Gateway ---- */
  M('edge-gw1-loss', 'gw1 · packet loss', 'edge', '%', 2, { base: .25, amp: .06, period: 95, noise: .05, dir: 'upBad', warn: 1, crit: 3, scripts: [ramp(70, 200, 3.2)] }),
