  m.flatNow = frozenAt(m, t) !== null && flatRange(m, m.hist) !== null;

  // state machine with 2-tick debounce (kills flapping → no flicker noise)
  const sev = Math.max(classify(m, v), m.flatNow ? 1 : 0);
  if (sev !== m.state) {
