  let dTxt = '·', dCls = 'flat';
  if (n > 60) {
    const ref = h[n - 61].v, d = v - ref;
    if (Math.abs(ref) > 1) {
      const p = d / ref * 100;
      if (Math.abs(p) >= .5) { dTxt = (d > 0 ? '▲' : '▼') + Math.abs(p).toFixed(1) + '%'; dCls = d > 0 ? 'up' : 'dn'; }
    } else {
      const dec = Math.max(m.dec, 2);
      if (Math.abs(d) >= Math.pow(10, -dec) / 2) { dTxt = (d > 0 ? '▲' : '▼') + Math.abs(d).toFixed(dec); dCls = d > 0 ? 'up' : 'dn'; }
    }
